const BATCH_SIZE = 200;
const ITEM_HEIGHT = 60;

// 虚拟滚动管理器
class SimpleVirtualList {
    constructor() {
        this.container = document.getElementById('scrollContainer');
        this.content = document.getElementById('scrollContent');
        this.searchInput = document.getElementById('searchInput');
        this.visibleCount = document.getElementById('visibleCount');
        this.loadedCount = document.getElementById('loadedCount');
        this.statusText = document.getElementById('statusText');
        
        this.filteredGames = ALL_GAMES;
        this.visibleItems = new Set();
        this.lastVisibleStart = -1;
        this.lastVisibleEnd = -1;
        
        this.init();
    }
    
    init() {
        console.log(`初始化虚拟列表，共 ${ALL_GAMES.length} 个游戏`);
        
        // 事件监听
        this.searchInput.addEventListener('input', () => this.handleSearch());
        this.container.addEventListener('scroll', () => this.handleScroll());
        document.getElementById('clearSearch').addEventListener('click', () => this.clearSearch());
        document.getElementById('scrollTop').addEventListener('click', () => this.scrollToTop());
        
        // 初始加载
        this.updateFilteredGames();
        this.loadVisibleItems();
        
        this.updateStatus('就绪');
    }
    
    handleSearch() {
        const searchTerm = this.searchInput.value.trim().toLowerCase();
        
        if (searchTerm === '') {
            this.filteredGames = ALL_GAMES;
        } else {
            this.filteredGames = ALL_GAMES.filter(game => 
                game.search.toLowerCase().includes(searchTerm) || 
                game.text.toLowerCase().includes(searchTerm)
            );
        }
        
        // 更新内容高度
        this.content.style.height = (this.filteredGames.length * ITEM_HEIGHT) + 'px';
        
        // 清空可见项
        this.content.innerHTML = '';
        this.visibleItems.clear();
        
        // 重新加载
        this.loadVisibleItems();
        
        this.updateStatus(`搜索: "${searchTerm}"，找到 ${this.filteredGames.length} 个结果`);
    }
    
    clearSearch() {
        this.searchInput.value = '';
        this.handleSearch();
        this.searchInput.focus();
    }
    
    scrollToTop() {
        this.container.scrollTop = 0;
        this.loadVisibleItems();
    }
    
    getVisibleRange() {
        const scrollTop = this.container.scrollTop;
        const containerHeight = this.container.clientHeight;
        
        const startIdx = Math.floor(scrollTop / ITEM_HEIGHT);
        const endIdx = Math.min(
            Math.ceil((scrollTop + containerHeight) / ITEM_HEIGHT),
            this.filteredGames.length
        );
        
        // 扩展范围，预加载一些额外项目
        const buffer = 20;
        const expandedStart = Math.max(0, startIdx - buffer);
        const expandedEnd = Math.min(this.filteredGames.length, endIdx + buffer);
        
        return { start: expandedStart, end: expandedEnd };
    }
    
    loadVisibleItems() {
        const { start, end } = this.getVisibleRange();
        
        // 如果范围相同，跳过
        if (start === this.lastVisibleStart && end === this.lastVisibleEnd) {
            return;
        }
        
        this.lastVisibleStart = start;
        this.lastVisibleEnd = end;
        
        // 计算要加载的范围（分批）
        const batchStart = Math.floor(start / BATCH_SIZE) * BATCH_SIZE;
        const batchEnd = Math.ceil(end / BATCH_SIZE) * BATCH_SIZE;
        
        // 移除当前不可见的项
        this.removeInvisibleItems(batchStart, batchEnd);
        
        // 添加新的可见项
        this.addVisibleItems(batchStart, batchEnd);
        
        // 更新计数
        this.visibleCount.textContent = this.filteredGames.length;
        this.loadedCount.textContent = this.visibleItems.size;
    }
    
    removeInvisibleItems(batchStart, batchEnd) {
        const itemsToRemove = [];
        
        this.visibleItems.forEach(id => {
            const idx = this.getIndexById(id);
            if (idx < batchStart || idx >= batchEnd) {
                itemsToRemove.push(id);
            }
        });
        
        itemsToRemove.forEach(id => {
            const element = document.getElementById(`game-${id}`);
            if (element) {
                element.remove();
            }
            this.visibleItems.delete(id);
        });
    }
    
    addVisibleItems(batchStart, batchEnd) {
        for (let i = batchStart; i < batchEnd && i < this.filteredGames.length; i++) {
            const game = this.filteredGames[i];
            const id = game.id;
            
            if (!this.visibleItems.has(id)) {
                this.createGameElement(game, i);
                this.visibleItems.add(id);
            }
        }
    }
    
    createGameElement(game, index) {
        const top = index * ITEM_HEIGHT;
        
        const div = document.createElement('div');
        div.className = 'game-item';
        div.id = `game-${game.id}`;
        div.style.position = 'absolute';
        div.style.top = `${top}px`;
        div.style.left = '0';
        div.style.right = '0';
        div.style.height = `${ITEM_HEIGHT - 2}px`;
        
        const searchTerm = this.searchInput.value.trim().toLowerCase();
        const highlightedText = this.highlightText(game.text, searchTerm);
        
        div.innerHTML = `
            <div class="game-header">
                <span class="game-id">#${game.id.toString().padStart(5, '0')}</span>
                <a href="${game.href}" class="game-link" target="_blank">${highlightedText}</a>
            </div>
        `;
        
        this.content.appendChild(div);
    }
    
    highlightText(text, searchTerm) {
        if (!searchTerm) return text;
        
        const regex = new RegExp(`(${this.escapeRegExp(searchTerm)})`, 'gi');
        return text.replace(regex, '<mark>$1</mark>');
    }
    
    escapeRegExp(string) {
        return string.replace(/[.*+?^${}()|[\]\\]/g, '\\$&');
    }
    
    getIndexById(id) {
        return this.filteredGames.findIndex(game => game.id === id);
    }
    
    handleScroll() {
        // 防抖处理
        if (this.scrollTimer) {
            clearTimeout(this.scrollTimer);
        }
        
        this.scrollTimer = setTimeout(() => {
            this.loadVisibleItems();
        }, 50);
    }
    
    updateStatus(text) {
        this.statusText.textContent = text;
    }
}

// 页面加载完成后初始化
document.addEventListener('DOMContentLoaded', () => {
    window.virtualList = new SimpleVirtualList();
    
    // 添加键盘快捷键
    document.addEventListener('keydown', (e) => {
        if (e.key === 'Escape') {
            window.virtualList.clearSearch();
        }
        if (e.key === '/' && e.target.tagName !== 'INPUT') {
            e.preventDefault();
            document.getElementById('searchInput').focus();
        }
    });
    
    // 初始聚焦搜索框
    document.getElementById('searchInput').focus();
});
